//! A partial Global reference is resumable without switching out of Modify.
//! This request deliberately stops at the Global boundary; unselected grids
//! must never be generated by this convenience path.
use super::*;

fn global_only_request_settings(settings:&document::Settings)->document::Settings{
    let mut request=settings.clone();request.pause_at_stage_end=true;request
}

impl PainterApp{
    pub(super) fn can_continue_reference_global(&self)->bool{
        if !self.is_redraw(){return false;}
        let Some(entry)=&self.save_session.active else{return false;};
        if !entry.workspace.selection.regions().is_empty(){return false;}
        if self.histories.stage_floor(&self.document,self.document.current).ok().flatten().unwrap_or(1)!=1{return false;}
        let Ok(legacy)=self.histories.stage_map(&self.document,self.document.current)else{return false;};
        let Ok(stages)=crate::redraw::stage_canvases(&self.document.primitives,&legacy)else{return false;};
        stages.coarse.is_empty()&&stages.fine.is_empty()
            &&stages.global.iter().any(|p|p.shape==ShapeKind::Background)
            &&stages.global.iter().filter(|p|p.shape!=ShapeKind::Background).count()<85
    }
    pub(super) fn start_reference_global_generation(&mut self,prompt:String,settings:document::Settings){
        let prepared=(||{
            if !self.can_continue_reference_global(){return Err("当前参考不是可继续的全图前缀".into());}
            settings.validate()?;
            inference::prompt_validation::PromptValidator::open(&self.tokenizer_path)
                .and_then(|validator|validator.validate(&prompt).into_token_ids())?;
            let settings=settings_for_generation(settings)?;
            let effective=self.histories.effective_history(&self.document,self.document.current)?;
            let by_id=self.document.primitives.iter().map(|p|(p.id,p)).collect::<std::collections::HashMap<_,_>>();
            let primitives=effective.primitive_ids.iter().map(|id|by_id.get(id).map(|p|(*p).clone())
                .ok_or("全图参考上下文引用了不存在的图元".to_owned())).collect::<Result<Vec<_>,_>>()?;
            let mut parallel=ParallelHistory::new(&self.document,self.document.current,prompt.clone(),settings.clone())?;
            parallel.initialize_model_input(&self.document,&self.histories)?;
            Ok::<_,String>((settings,effective.records,primitives,parallel))
        })();
        let(settings,records,primitives,parallel)=match prepared{Ok(value)=>value,Err(error)=>{self.editor.notify(error);return;}};
        self.document.prompt=prompt;self.document.settings=settings;self.parallel=Some(parallel);
        self.running=true;self.stopping=false;self.error=None;self.save_session.mark_dirty();
        let request=global_only_request_settings(&self.document.settings);
        self.runtime.generate_with_stage_context(self.document.prompt.clone(),request,primitives,Some(records),
            Vec::new(),Vec::new(),None,Vec::new(),None);
        self.status="正在修改模式下继续全图绘制；全图阶段结束后自动停下".into();
        diagnostics::event("reference_global_continuation_requested",serde_json::json!({"global_only":true,
            "request_local_stage_pause":true,"stored_stage_pause":self.document.settings.pause_at_stage_end}));
    }
}

#[cfg(test)]mod tests{
    use super::*;
    #[test]fn global_reference_request_pauses_at_boundary_without_changing_user_preferences(){
        for stored in [false,true]{
            let settings=document::Settings{pause_at_stage_end:stored,parallel_sequences:8,..Default::default()};
            let request=global_only_request_settings(&settings);
            assert!(request.pause_at_stage_end);assert_eq!(settings.pause_at_stage_end,stored);
            let mut expected=settings.clone();expected.pause_at_stage_end=true;assert_eq!(request,expected);
        }
    }
}
